<?php
session_start(); require 'config.php'; require 'functions.php'; verify_csrf(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(isset($_POST['delete_id'])){$pdo->prepare("DELETE FROM tournaments WHERE tournament_id=?")->execute([int_post('delete_id')]);flash('Tournament deleted.');redirect('tournaments.php');}
  if(isset($_POST['save_tournament'])){$name=trim((string)post('name'));$game=trim((string)post('game'));$format=trim((string)post('format'));$status=trim((string)post('status'));$date=trim((string)post('start_date'));$max=int_post('max_teams');$id=int_post('tournament_id');if($name===''||$game==='')throw new RuntimeException('Tournament name and game are required.');if($max<2)throw new RuntimeException('Maximum teams must be at least 2.');if($id){$st=$pdo->prepare("UPDATE tournaments SET name=?,game=?,format=?,status=?,start_date=?,max_teams=? WHERE tournament_id=?");$st->execute([$name,$game,$format,$status,$date?:null,$max,$id]);flash('Tournament updated.');}else{$st=$pdo->prepare("INSERT INTO tournaments(name,game,format,status,start_date,max_teams) VALUES(?,?,?,?,?,?)");$st->execute([$name,$game,$format,$status,$date?:null,$max]);flash('Tournament created.');}redirect('tournaments.php');}
  if(isset($_POST['register_team'])){$tid=int_post('tournament_id');$team=int_post('team_id');$st=$pdo->prepare("SELECT COUNT(*) FROM tournament_registrations WHERE tournament_id=?");$st->execute([$tid]);$count=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT max_teams FROM tournaments WHERE tournament_id=?");$st->execute([$tid]);$max=(int)$st->fetchColumn();if($count >= $max)throw new RuntimeException('This tournament has reached its team limit.');$pdo->prepare("INSERT INTO tournament_registrations(tournament_id,team_id) VALUES(?,?)")->execute([$tid,$team]);flash('Team registered for tournament.');redirect('tournaments.php');}
  if(isset($_POST['unregister_team'])){$pdo->prepare("DELETE FROM tournament_registrations WHERE tournament_id=? AND team_id=?")->execute([int_post('tournament_id'),int_post('team_id')]);flash('Team unregistered.');redirect('tournaments.php');}
 }catch(Throwable $e){$error=$e instanceof PDOException&&$e->getCode()==='23000'?'That team is already registered, or this tournament has matches and cannot be deleted yet.':$e->getMessage();}
}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM tournaments WHERE tournament_id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}
$teams=$pdo->query("SELECT team_id,name FROM teams ORDER BY name")->fetchAll();
$tournaments=$pdo->query("SELECT t.*,(SELECT COUNT(*) FROM tournament_registrations tr WHERE tr.tournament_id=t.tournament_id) team_count FROM tournaments t ORDER BY t.created_at DESC")->fetchAll();
$regs=$pdo->query("SELECT tr.tournament_id,tr.team_id,t.name team_name FROM tournament_registrations tr JOIN teams t ON t.team_id=tr.team_id ORDER BY t.name")->fetchAll();
page_header('Tournaments','tournaments');
?>
<div class="page-heading"><div><h1>Tournaments</h1><p>Create multi-game events and register competing teams.</p></div><span class="tag"><?= count($tournaments) ?> events</span></div>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-xl-4"><div class="cardx"><div class="section-title"><?= $edit?'Edit tournament':'Create tournament' ?></div><form method="post"><?= csrf_field() ?><input type="hidden" name="tournament_id" value="<?= e($edit['tournament_id']??'') ?>"><div class="mb-3"><label class="form-label">Tournament name *</label><input class="form-control" name="name" required value="<?= e($edit['name']??'') ?>" placeholder="ArenaX Open #1"></div><div class="mb-3"><label class="form-label">Game *</label><select class="form-select" name="game" required><?php foreach(['BGMI','Valorant','Free Fire','Counter-Strike 2','Dota 2','League of Legends','Call of Duty','Rocket League','Other'] as $g): ?><option <?= ($edit['game']??'')===$g?'selected':'' ?>><?= e($g) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Format</label><select class="form-select" name="format"><?php foreach(['Single Elimination','Double Elimination','Round Robin','Battle Royale'] as $f): ?><option <?= ($edit['format']??'Single Elimination')===$f?'selected':'' ?>><?= e($f) ?></option><?php endforeach; ?></select></div><div class="row"><div class="col-7 mb-3"><label class="form-label">Start date</label><input class="form-control" type="date" name="start_date" value="<?= e($edit['start_date']??'') ?>"></div><div class="col-5 mb-3"><label class="form-label">Max teams</label><input class="form-control" type="number" min="2" max="256" name="max_teams" value="<?= e($edit['max_teams']??8) ?>" required></div></div><div class="mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['upcoming','ongoing','completed'] as $s): ?><option value="<?= $s ?>" <?= ($edit['status']??'upcoming')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary w-100" name="save_tournament" value="1"><?= $edit?'Save changes':'Create tournament' ?></button><?php if($edit): ?><a href="tournaments.php" class="btn btn-outline-light w-100 mt-2">Cancel</a><?php endif; ?></form></div></div>
<div class="col-xl-8"><div class="row g-3"><?php foreach($tournaments as $t): ?><div class="col-lg-6"><div class="cardx h-100"><div class="d-flex justify-content-between align-items-start mb-3"><span class="tag"><?= e($t['game']) ?></span><span class="tag <?= $t['status']==='completed'?'tag-green':($t['status']==='ongoing'?'tag-yellow':'') ?>"><?= e(ucfirst($t['status'])) ?></span></div><h5 class="fw-bold"><?= e($t['name']) ?></h5><div class="small muted mb-3"><?= e($t['format']) ?> · <?= $t['start_date']?e(date('M j, Y',strtotime($t['start_date']))):'Date TBD' ?></div><div class="d-flex justify-content-between small mb-3"><span class="muted">Registered teams</span><span><?= (int)$t['team_count'] ?> / <?= (int)$t['max_teams'] ?></span></div><div class="progress mb-3" style="height:5px;background:#292f3d"><div class="progress-bar" style="width:<?= min(100,(int)$t['team_count']/(int)$t['max_teams']*100) ?>%;background:#a78bfa"></div></div><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-light" href="tournaments.php?edit=<?= (int)$t['tournament_id'] ?>"><i class="bi bi-pencil"></i> Edit</a><?= delete_button('tournaments.php',(int)$t['tournament_id']) ?></div></div></div><?php endforeach; ?></div><?php if(!$tournaments): ?><div class="cardx empty-state"><i class="bi bi-trophy"></i>No tournaments yet. Create your first event.</div><?php endif; ?>
<div class="cardx mt-4"><div class="section-title">Register a team</div><?php if(!$tournaments||!$teams): ?><div class="small-note">Create a tournament and at least one team first.</div><?php else: ?><form method="post" class="row g-3 align-items-end"><?= csrf_field() ?><div class="col-md-5"><label class="form-label">Tournament</label><select class="form-select" name="tournament_id"><?php foreach($tournaments as $t): ?><option value="<?= (int)$t['tournament_id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-5"><label class="form-label">Team</label><select class="form-select" name="team_id"><?php foreach($teams as $t): ?><option value="<?= (int)$t['team_id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-primary w-100" name="register_team" value="1">Register</button></div></form><?php endif; ?>
<?php foreach($tournaments as $t): $tr=array_values(array_filter($regs,fn($r)=>(int)$r['tournament_id']===(int)$t['tournament_id'])); if($tr): ?><div class="mt-4"><div class="small muted mb-2"><?= e($t['name']) ?> · registered teams</div><?php foreach($tr as $r): ?><span class="tag me-1 mb-1"><?= e($r['team_name']) ?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="tournament_id" value="<?= (int)$t['tournament_id'] ?>"><input type="hidden" name="team_id" value="<?= (int)$r['team_id'] ?>"><button class="btn p-0 ms-1" style="color:#fda4af;font-size:10px" name="unregister_team" value="1" title="Unregister">×</button></form></span><?php endforeach; ?></div><?php endif; endforeach; ?></div></div></div>
<?php page_footer(); ?>
